 Certainly! Here's a JavaScript function that uses regular expressions and string manipulation to switch the order of adjectives in a sentence:

```javascript
function switchAdjectiveOrder(sentence) {
  // Define a regex pattern to match adjectives before nouns
  const adjectivePattern = /(([a-z]+[^ ]+[a-z]*)|[Jj][o][s][e]s|[A-Z][a-z]+[a-z]*[^ ]+(?: [A-Z][a-z]+[a-z]*)*) ([a-z]+[^ ]+[a-z]*)/g;

  let match, result = [];
  let currentAdjectiveIndex = -1;

  while ((match = adjectivePattern.exec(sentence)) !== null) {
    currentAdjectiveIndex++;
    result.push(match[2]); // Save the second group (noun) for later
    result.unshift(match[1]); // Move the first group (adj) to the beginning of the temporary array
  }

  // Reconstruct the sentence with swapped adjectives
  return result.slice(currentAdjectiveIndex).concat(result.slice(0, currentAdjectiveIndex)).join(' ') + ' ' + result[result.length - 1]; // Add the last noun back at the end
}

// Test cases
console.log(switchAdjectiveOrder("Beautiful green trees are in the park")); // "Green beautiful trees are in the park"
console.log(switchAdjectiveOrder("Red and tall buildings")); // "Tall red and buildings"
console.log(switchAdjectiveOrder("The old brown fox jumps over the lazy dog")); // "The lazy dog jumps over the brown old fox"
console.log(switchAdjectiveOrder("Majestic blue whales swim in the ocean")); // "Blue majestic whales swim in the ocean"
```

