  if (ipVersion === 6 && inputData.port === 80) { // If IP version is IPv6 and port is HTTP
    return "HTTP over IPv6 (Option B)";
  } else if (ipVersion === 6) { // If IP version is IPv6 and it's not HTTP
    return "UDP over IPv6 (Option C)";
  } else if (inputData.port === 80) { // If it's IPv4 and port is HTTP
    return "HTTP over IPv4 (Option B)";
  } else { // Otherwise, it must be UDP
    return "UDP (Option C)";
  }
}
function getIPVersion(ip1, ip2) {
  const ip1Parts = ip1.split(':').length > 7 ? ip1.split(':') : ip1.split('.');
  const ip2Parts = ip2.split(':').length > 7 ? ip2.split(':') : ip2.split('.');

  if (ip1Parts.length === 8 && ip2Parts.length === 8) { // Both are IPv6
    return 6;
  } else { // Both are IPv4
    return 4;
  }
}
```
