 I'd be happy to help you write a Google Apps Script to search for a place name using the Google Maps Geocoding API and store the latitude and longitude in separate columns of a Google Spreadsheet. Here's an example script that demonstrates how to do this:

```javascript
function geocodePlaces() {
  // Replace "Sheet1" with the name of your sheet
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getActiveSheet();
  const dataRange = sheet.getDataRange();
  const values = dataRange.getValues();

  // Define the API key and the columns to store the latitude and longitude
  const apiKey = 'YOUR_API_KEY';
  const latColumn = 2;
  const lngColumn = 3;

  for (let i = 1; i < values.length; i++) {
    const placeName = values[i][0]; // Assuming the place name is in the first column

    try {
      const url = `https://maps.googleapis.com/maps/api/geocode/json?address=${encodeURIComponent(placeName)}&key=${apiKey}`;
      const response = UrlFetchApp.fetch(url);
      const json = JSON.parse(response.getContentText());

      if (json.status === 'OK') {
        const location = json.results[0].geometry.location;
        sheet.getRange(i + 1, latColumn).setValue(location.lat);
        sheet.getRange(i + 1, lngColumn).setValue(location.lng);
      } else {
        Logger.log(`Error geocoding "${placeName}": ${json.statusMessage}`);
      }
    } catch (e) {
      Logger.log('Error fetching data from the Geocoding API:', e);
    }
  }

  Logger.log('Geocoding completed.');
}
```

