function smart_sort_array($set, $order = 'ASC') {
    $size = count($set);
    for ($i = 0; $i < $size - 1; $i++) {
        for ($j = $i + 1; $j < $size; $j++) {
            if (($order == 'DESC' && $set[$i]['age'] < $set[$j]['age']) || ($order == 'ASC' && $set[$i]['age'] > $set[$j]['age'])) {
                // Swap elements i and j
                $temp = $set[$i];
                $set[$i] = $set[$j];
                $set[$j] = $temp;
            }
        }
    }
    return $set;
}
