 To retrieve the username from a JWT (JSON Web Token) in an ASP.NET C# WebAPI, you can use the `JwtSecurityTokenHandler` class from the `System.IdentityModel.Tokens.Jwt` namespace. Here's how to do it:

1. First, make sure you have installed the `Microsoft.AspNetCore.Authentication.JwtBearer` NuGet package for handling JWT authentication in your project. If not, install it using the following command in the Package Manager Console:

```sh
Install-Package Microsoft.AspNetCore.Authentication.JwtBearer
```

2. In your controller or extension method, write the code to extract the username from the JWT token:

```csharp
using System;
using System.IdentityModel.Tokens.Jwt;
using Microsoft.AspNetCore.Mvc;

[Route("api/[controller]")]
[ApiController]
public class ValuesController : ControllerBase
{
    // Your actions here...

    [HttpGet("getUsernameFromToken")]
    public ActionResult<string> GetUsernameFromToken([FromHeader(Name = "Authorization")] string authHeader)
    {
        try
        {
            // Remove the 'Bearer ' prefix from the token
            var token = authHeader.Replace("Bearer ", String.Empty);

            // Parse and validate the token
            var handler = new JwtSecurityTokenHandler();
            SecurityToken securityToken;
            JwtSecurityToken jwtToken = handler.ReadJwtToken(token) as JwtSecurityToken;

            if (jwtToken == null)
                return BadRequest("Invalid token.");

            // Extract the username from the claims
            string username = jwtToken.Claims.FirstOrDefault(x => x.Type == ClaimTypes.Name)?.Value;

            if (username == null)
                return BadRequest("Unable to get username from token.");

            return Ok(username);
        }
        catch (Exception ex)
        {
            return BadRequest($"Error getting username from token: {ex.Message}");
        }
    }
}
```

