using UnityEngine;

public class AudioVisualizer : MonoBehaviour
{
    public AudioClip audioClip;
    public float amplitudeSensitivity = 1f; // Adjust this value for more or less intense visualizer effect
    public int barCount = 64; // Number of bars in the visualizer

    private float[] samples = new float[barCount];
    private RectTransform[] bars;

    private void Start()
    {
        GetComponentsInChildren(out AudioSource audioSource);
        audioSource.clip = audioClip;
        audioSource.loop = true;
        audioSource.Play();

        bars = new RectTransform[transform.childCount];
        for (int i = 0; i < transform.childCount; i++)
        {
            bars[i] = transform.GetChild(i).GetComponent<RectTransform>();
        }
    }

    private void Update()
    {
        if (audioSource.isPlaying)
        {
            GetSpectrumData();
            UpdateBars();
        }
    }

    private void GetSpectrumData()
    {
        audioSource.GetSpectrumData(samples, 0, FFTWindow.BlackmanHarris);
    }

    private void UpdateBars()
    {
        for (int i = 0; i < samples.Length; i++)
        {
            bars[i].localScale = new Vector3(bars[i].localScale.x, Mathf.Lerp(bars[i].localScale.y, samples[i] * amplitudeSensitivity, Time.deltaTime), bars[i].localScale.z);
        }
    }
}
```

