 Here's an example of how you can create a decorator for Nest.js middleware that checks the `NODE_ENV` environment variable and either calls the next middleware function or returns `false`. I'll assume you have some basic understanding of Nest.js and decorators.

First, let's define the `CheckNodeEnvDecorator`:

```typescript
import { CreateContextDecoder, createParamDecorator, ExecutionContext } from '@nestjs/common';

export const CheckNodeEnv = createParamDecorator(
  (data: unknown, ctx: ExecutionContext) => {
    const request = ctx.switchToHttp().getRequest();
    return request.nodeEnv;
  },
);

@CreateContextDecoder()
export class CheckNodeEnvContextKey {}

export const CheckNodeEnvMiddleware = () => {
  return (req: Request, res: Response, next: Function) => {
    const nodeEnv = CheckNodeEnv();

    if (nodeEnv === 'production' || process.env.NODE_ENV === 'production') {
      next();
    } else {
      res.status(403).json({ message: 'Access denied in non-production environment.' });
    }
  };
};

export const CheckNodeEnvDecorator = () => {
  return (target: Object, key: string, desc: PropertyDescriptor) => {
    Reflect.defineMetadata('decoratorKey', CheckNodeEnvContextKey.name, target, key);
    Reflect.defineMetadata('middleware', CheckNodeEnvMiddleware(), target, key);
  };
};
```

Now, let's use this decorator on a controller method or route:

```typescript
