import { CheckNodeEnvDecorator } from './check-node-env.decorator';

@Controller()
export class AppController {
  @Get('/protected')
  @UseGuards(CheckNodeEnvGuard()) // or CheckNodeEnvDecorator()
  getProtected(): any {
    // Your protected logic here
  }
}
