import React from 'react';
import { Text } from 'react-text'; // Import Text component from react-text

const NoWidowLine = ({ children }) => {
  const [lines, setLines] = React.useState([]);

  const handleTextLayoutChange = (event) => {
    const { offsetWidth, clientHeight, getLine, lineCount } = event;
    const linesArray = Array.from({ length: lineCount }, (_, index) => getLine(index));
    setLines(linesArray);
  };

  return (
    <Text onTextLayout={handleTextLayoutChange}>
      {React.Children.map(children, (child, index) => (
        <span key={index}>
          {child}
          {lines[index + 1] && lines[index + 1].length < offsetWidth && '\u00A0'}
        </span>
      ))}
    </Text>
  );
};

export default NoWidowLine;
